let opsState={},opsTab='orders',opsOrderDraft=null,opsSupplierDraft=null,opsShiftDraft=null,opsPlan=null,opsRecorder=null,opsRecordingStream=null,opsRecordTimer=null,opsReportResult=null;
const opsStatusNames={new:'Новый',accepted:'Принят',preparing:'В работе',ready:'Готов',completed:'Завершён',cancelled:'Отменён',refunded:'Возврат отмечен',requested:'Ждёт подтверждения',confirmed:'Подтверждено',open:'Новое',working:'В работе',resolved:'Решено',proposed:'Проверка владельцем',executed:'Выполнено',failed:'Ошибка',review:'На проверке',applied:'Применён',undone:'Отменён',queued:'Ожидает отправки',sending:'Проверить доставку',sent:'Отправлено'};
const opsTabs={orders:'Заказы',calendar:'Расписание',stock:'Остатки и состав',tickets:'Обращения',results:'Результаты и спрос',budget:'Подбор по бюджету',scenario:'Что будет, если…',suppliers:'Поставщики',shifts:'Передача смены',passports:'История обслуживания',feedback:'Отзывы по QR',imports:'Импорт и история',team:'Команда',setup:'Подготовка бизнеса'};
function opsAllowedTabs(){return Object.entries(opsTabs).filter(([k])=>opsState.role==='operator'?['orders','calendar','tickets','budget','shifts','passports'].includes(k):opsState.role==='manager'?!['team','setup','feedback'].includes(k):true)}
function opsSelect(name,label,options,value='',extra=''){return '<div class="field"><label for="ops_'+name+'">'+esc(I18n.t(label))+'</label><select id="ops_'+name+'" name="'+name+'" '+extra+'>'+options.map(x=>'<option value="'+esc(x[0])+'" '+(String(x[0])===String(value)?'selected':'')+'>'+esc(x[2]===true?x[1]:I18n.t(x[1]))+'</option>').join('')+'</select></div>'}
function opsStaffOptions(){return [[0,'Не назначен'],...(opsState.staff||[]).filter(x=>Number(x.active)).map(x=>[x.id,x.name,true])]}
function opsItemOptions(service=false){return (state.catalog||[]).filter(x=>!service||x.details?.kind==='service').map(x=>[x.id,x.item_name+' · '+money(x.item_price),true])}
function opsButton(text,call,light=true){return '<button type="button" class="btn '+(light?'light ':'')+'small" onclick="'+call+'">'+esc(I18n.t(text))+'</button>'}
function opsGo(tab){opsTab=tab;if(location.hash!=='#operations')location.hash='operations';else render()}
function operationsPage(){if(!opsAllowedTabs().some(([k])=>k===opsTab))opsTab=opsAllowedTabs()[0]?.[0]||'orders';const panels={orders:opsOrdersPanel,calendar:opsCalendarPanel,stock:opsStockPanel,tickets:opsTicketsPanel,results:opsResultsPanel,budget:opsBudgetPanel,scenario:opsScenarioPanel,suppliers:opsSuppliersPanel,shifts:opsShiftsPanel,passports:opsPassportsPanel,feedback:opsFeedbackPanel,imports:opsImportsPanel,team:opsTeamPanel,setup:opsSetupPanel};return head('Работа и заказы','От запроса клиента до выполненного заказа и результата.')+'<div class="card" style="margin-bottom:20px;padding:16px">'+opsSelect('section','Раздел',opsAllowedTabs(),opsTab,'onchange="opsGo(this.value)"')+'</div>'+(panels[opsTab]||opsOrdersPanel)()}
async function opsRefresh(){await reload();render()}
async function opsAction(action,data,success='Сохранено'){try{const r=await api(action,data);await opsRefresh();toast(success);return r}catch(e){toast(e.message);return null}}
function opsOrdersPanel(){const rows=opsState.orders||[];return I18n.html("<section class=\"card\"><div class=\"sectiontitle\"><h2>Заказы и выполнение</h2>")+opsButton('＋ Новый заказ','opsOpenOrder()',false)+I18n.html("</div><p class=\"hint\">При создании резервируются связанные пригодные партии. При завершении остаток списывается. Отмена освобождает резерв. Демонстрационные заказы не входят в финансовый отчёт.</p>")+(rows.length?rows.map(o=>'<div class="row"><div><b>№'+o.id+' · '+esc(o.data.client)+' · '+money(o.total)+'</b><small>'+esc(o.created_at)+' · '+esc(I18n.t(opsStatusNames[o.status]||o.status))+' · '+(o.source==='telegram'?'Telegram':I18n.t("Кабинет"))+(Number(o.is_demo)?I18n.t(" · ДЕМОНСТРАЦИЯ"):'')+'</small><small>'+(o.data.items||[]).map(x=>esc(x.name)+' × '+x.quantity).join(', ')+'</small></div>'+opsButton('Открыть','opsOrderDetails('+o.id+')')+'</div>').join(''):empty('Заказы появятся здесь после подтверждения клиентом или сотрудником.'))+'</section>'}
function opsOpenOrder(items=null){const quantities=Object.fromEntries((items||[]).map(x=>[x.item_id,x.quantity]));modal('Собрать заказ','<form onsubmit="opsQuoteOrder(event)"><div class="fields">'+field('client','Клиент','text','Гость','required')+field('phone','Телефон','tel')+field('pickup_at','Пожелание по получению','text','','placeholder="Например, сегодня в 18:30"')+field('campaign_code','Промокод','text')+textfield('note','Комментарий')+I18n.html("</div><div class=\"tablewrap\"><table><thead><tr><th>Позиция</th><th>Цена</th><th>Количество</th></tr></thead><tbody>")+(state.catalog||[]).map(x=>'<tr><td>'+esc(x.item_name)+(x.details?.data_mode==='demo'?I18n.html(" <span class=\"badge\">Пример</span>"):'')+'</td><td>'+money(x.item_price)+'</td><td><input style="width:100px" type="number" data-order-item="'+x.id+'" value="'+(quantities[x.id]||0)+I18n.t("\" min=\"0\" max=\"10000\" step=\"0.001\" aria-label=\"Количество ")+esc(x.item_name)+'"></td></tr>').join('')+I18n.html("</tbody></table></div><div class=\"actions\"><button class=\"btn\">Проверить цену и наличие</button></div></form>"))}
async function opsQuoteOrder(ev){ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{const d=formData(ev.target);d.items=[...ev.target.querySelectorAll('[data-order-item]')].filter(x=>Number(x.value)>0).map(x=>({item_id:Number(x.dataset.orderItem),quantity:Number(x.value)}));const q=await api('ops_quote',d);opsOrderDraft={...d,quote_hash:q.hash,request_key:crypto.randomUUID()};opsShowQuote(q,'opsConfirmOrder()')}catch(e){toast(e.message);b.disabled=false}}
function opsShowQuote(q,call,extra=''){modal('Проверьте перед подтверждением',(q.is_demo?I18n.html("<p class=\"notice\">Демонстрационный заказ. Он не попадёт в реальные продажи.</p>"):'')+q.items.map(x=>'<div class="row"><span>'+esc(x.name)+' × '+x.quantity+'</span><b>'+money(x.total)+'</b></div>').join('')+I18n.html("<h2>Итого: ")+money(q.total)+'</h2>'+extra+(q.warnings?.length?'<p class="hint">'+q.warnings.map(esc).join('<br>')+'</p>':'')+I18n.html("<p class=\"hint\">Оплата не проводится автоматически.</p><div class=\"actions\">")+opsButton('Подтвердить',call,false)+'</div>')}
async function opsConfirmOrder(){try{const r=await api('ops_order_create',opsOrderDraft);$('modal').close();await opsRefresh();toast('Создан заказ №'+r.id)}catch(e){toast(e.message)}}
function opsOrderDetails(id){const o=opsState.orders.find(x=>Number(x.id)===id),next={new:['accepted','cancelled'],accepted:['preparing','ready','completed','cancelled'],preparing:['ready','completed','cancelled'],ready:['completed','cancelled'],completed:opsState.role==='operator'?[]:['refunded']}[o.status]||[];modal('Заказ №'+id,'<p>'+esc(I18n.t(opsStatusNames[o.status]))+' · '+esc(o.created_at)+'</p>'+o.data.items.map(x=>'<div class="row"><span>'+esc(x.name)+' × '+x.quantity+'</span><b>'+money(x.total)+'</b></div>').join('')+'<h2>'+money(o.total)+'</h2><p>'+esc(o.data.client)+' · '+esc(o.data.phone||'')+'</p><p>'+esc(o.data.pickup_at||'')+'</p><p>'+esc(o.data.note||'')+'</p><div class="actions">'+next.filter(s=>!['preparing','ready'].includes(s)||!(opsState.appointments||[]).some(a=>Number(a.data.order_id)===id)).map(s=>opsButton(opsStatusNames[s],"opsReviewStatus("+id+",'"+s+"')")).join('')+'</div>')}
function opsReviewStatus(id,status){modal('Изменить статус заказа',I18n.html("<p>Заказ №")+id+': '+esc(I18n.t(opsStatusNames[status]))+'.</p>'+(status==='completed'?I18n.html("<p>Пригодные зарезервированные партии будут списаны, а заказ попадёт в отчёт.</p>"):status==='cancelled'?I18n.html("<p>Резерв товаров будет освобождён.</p>"):status==='refunded'?I18n.html("<p>Отмечайте только фактически оформленный возврат. Денежный перевод клиенту приложение не выполняет.</p><label><input type=\"checkbox\" id=\"opsRestock\"> Товар физически возвращён и пригоден для продажи — пополнить исходные партии</label>"):'')+'<div class="actions">'+opsButton('Подтвердить',"opsSetStatus("+id+",'"+status+"')",false)+'</div>')}
async function opsSetStatus(id,status){const restock=!!$('opsRestock')?.checked;const r=await opsAction('ops_order_status',{id,status,restock});if(r)$('modal').close()}
function opsCalendarPanel(){return I18n.html("<section class=\"card\"><div class=\"sectiontitle\"><h2>Записи с длительностью</h2><div class=\"actions\">")+(opsState.role!=='operator'?opsButton('Мастера и часы','opsOpenResource()'):'')+opsButton('＋ Записать клиента','opsOpenBooking()',false)+I18n.html("</div></div><p class=\"hint\">Рабочие часы и перерывы задаются для каждого ресурса. Время UTC+5. Подтверждённые старые записи с тем же названием ресурса учитываются как 60 минут.</p>")+(opsState.appointments||[]).map(a=>'<div class="row"><div><b>'+esc(a.data.client)+' · '+esc(a.data.name)+'</b><small>'+esc(a.starts_at)+' — '+esc(a.ends_at.slice(11,16))+' · '+esc(a.data.resource)+' · '+esc(I18n.t(opsStatusNames[a.status]))+(a.data.is_demo?I18n.t(" · Пример"):'')+'</small></div><div class="actions">'+(['requested','confirmed'].includes(a.status)?opsButton('Перенести','opsOpenBooking('+a.id+')')+opsButton('Отменить',"opsAppointmentStatus("+a.id+",'cancelled')"):'')+(a.status==='requested'?opsButton('Подтвердить',"opsAppointmentStatus("+a.id+",'confirmed')",false):a.status==='confirmed'?opsButton('Завершить',"opsAppointmentStatus("+a.id+",'completed')",false):'')+'</div></div>').join('')+I18n.html("</section><section class=\"card\" style=\"margin-top:20px\"><h2>Мастера, столы и кабинеты</h2>")+(opsState.resources||[]).map(r=>'<div class="row"><div><b>'+esc(r.name)+'</b><small>'+Object.entries(r.data.hours).map(([d,h])=>['','Пн','Вт','Ср','Чт','Пт','Сб','Вс'][d]+' '+h.start+'–'+h.end).join(' · ')+'</small></div>'+(opsState.role!=='operator'?opsButton('Настроить','opsOpenResource('+r.id+')'):'')+'</div>').join('')+'</section>'}
function opsOpenResource(id=0){const r=opsState.resources.find(x=>Number(x.id)===id)||{data:{hours:{},service_ids:[]}};modal('Ресурс и рабочее время','<form onsubmit="opsSaveResource(event,'+id+')"><div class="fields">'+field('name','Мастер / стол / кабинет','text',r.name||'','required')+textfield('note','Примечание','',r.data.note||'')+I18n.html("</div><h3>Услуги этого ресурса</h3><div class=\"fields\">")+opsItemOptions(true).map(([key,label])=>'<label><input type="checkbox" name="service" value="'+key+'" '+(r.data.service_ids.includes(Number(key))?'checked':'')+'> '+esc(label)+'</label>').join('')+I18n.html("</div><p class=\"hint\">Если услуг нет, в каталоге измените тип нужной позиции на «Услуга» и задайте длительность.</p><div class=\"tablewrap\"><table><thead><tr><th>День</th><th>Начало</th><th>Конец</th><th>Перерыв с</th><th>до</th></tr></thead><tbody>")+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((label,i)=>{const h=r.data.hours[i+1];return '<tr><td><label><input type="checkbox" id="opsDay'+(i+1)+'" '+(h?'checked':'')+'> '+label+'</label></td>'+['start','end','break_start','break_end'].map((k,n)=>'<td><input type="time" id="opsTime'+(i+1)+k+'" value="'+esc(h?.[k]||(n===0?'09:00':n===1?'18:00':''))+'" aria-label="'+label+' '+k+'"></td>').join('')+'</tr>'}).join('')+I18n.html("</tbody></table></div><button class=\"btn\" type=\"submit\">Сохранить расписание</button></form>"))}
async function opsSaveResource(ev,id){ev.preventDefault();const d=formData(ev.target);d.id=id;d.service_ids=[...ev.target.querySelectorAll('[name=service]:checked')].map(x=>Number(x.value));d.hours={};for(let day=1;day<=7;day++)d.hours[day]={enabled:$('opsDay'+day).checked,...Object.fromEntries(['start','end','break_start','break_end'].map(k=>[k,$('opsTime'+day+k).value]))};const r=await opsAction('ops_resource_save',{data:d});if(r)$('modal').close()}
function opsOpenBooking(id=0){const a=opsState.appointments.find(x=>Number(x.id)===id),d=a?.data||{};modal(id?'Перенести запись':'Новая запись','<form onsubmit="opsReviewBooking(event,'+id+')"><div class="fields">'+field('client','Клиент','text',d.client||'','required')+field('phone','Телефон','tel',d.phone||'')+opsSelect('item_id','Услуга',opsItemOptions(true),a?.item_id||'')+opsSelect('resource_id','Мастер / ресурс',(opsState.resources||[]).filter(x=>Number(x.active)).map(x=>[x.id,x.name,true]),a?.resource_id||'')+field('date','Дата','date',a?.starts_at.slice(0,10)||today(),'required')+field('starts_at','Дата и время','datetime-local',a?.starts_at.slice(0,16).replace(' ','T')||'','required')+textfield('note','Комментарий','',d.note||'')+'</div><div class="actions">'+opsButton('Показать свободное время','opsFindSlots(this.form)')+'</div><div id="opsSlots"></div><label><input type="checkbox" name="reminder_optin" '+(d.reminder_optin?'checked':'')+I18n.html("> Клиент согласен на напоминание в Telegram (для записей из Telegram)</label><div class=\"actions\"><button class=\"btn\">Проверить запись</button></div></form>"))}
async function opsFindSlots(form){try{const d=formData(form);const r=await api('ops_slots',d);$('opsSlots').innerHTML=r.slots.length?'<div class="chips">'+r.slots.map(s=>'<button type="button" class="chip" onclick="document.querySelector(\'[name=starts_at]\').value=\''+s.starts_at.slice(0,16).replace(' ','T')+'\'">'+s.starts_at.slice(11,16)+'</button>').join('')+'</div>':I18n.html("<p class=\"notice\">Свободных окон нет или услуга не назначена этому ресурсу.</p>")}catch(e){toast(e.message)}}
async function opsReviewBooking(ev,id){ev.preventDefault();try{const d={...formData(ev.target),id,reminder_optin:ev.target.reminder_optin.checked};const q=await api('ops_quote',{items:[{item_id:Number(d.item_id),quantity:1}]});opsOrderDraft={...d,quote_hash:q.hash,request_key:crypto.randomUUID()};opsShowQuote(q,'opsConfirmBooking()','<p>'+esc(d.starts_at.replace('T',' '))+' · UTC+5</p>')}catch(e){toast(e.message)}}
async function opsConfirmBooking(){const r=await opsAction('ops_appointment_save',{data:opsOrderDraft});if(r)$('modal').close()}
async function opsAppointmentStatus(id,status){modal('Статус записи',I18n.html("<p>Запись №")+id+': '+esc(I18n.t(opsStatusNames[status]))+'.</p><div class="actions">'+opsButton('Подтвердить',"opsApplyAppointmentStatus("+id+",'"+status+"')",false)+'</div>')}
async function opsApplyAppointmentStatus(id,status){const r=await opsAction('ops_appointment_status',{id,status});if(r)$('modal').close()}
function opsStockPanel(){return I18n.html("<section class=\"card\"><h2>Партии, резерв и состав</h2><p>В каталоге включите учёт по партиям. Для блюда выберите состав из ингредиентов, которые учитываются по партиям. Количество ингредиента указывается в его базовой единице: например, 0,2 л молока на один напиток.</p><div class=\"actions\">")+opsButton('Добавить партию',"openResource('stock_batches')",false)+I18n.html("<a class=\"btn light\" href=\"#catalog\">Настроить позиции и состав</a></div><div class=\"tablewrap\"><table><thead><tr><th>Партия</th><th>Связана с</th><th>Физически</th><th>Резерв</th><th>Свободно</th><th>Годен до</th><th></th></tr></thead><tbody>")+(opsState.batches||[]).map(b=>'<tr><td>'+esc(b.data.name)+'</td><td>'+esc(state.catalog.find(x=>Number(x.id)===Number(b.data.item_id))?.item_name||'Не связана')+'</td><td>'+b.data.quantity+' '+esc(b.data.unit)+'</td><td>'+b.reserved+'</td><td>'+(b.eligible?b.free:I18n.t("Нельзя продавать"))+'</td><td>'+esc(b.data.expires_on||'—')+'</td><td>'+opsButton('Изменить',"openResource('stock_batches',"+b.id+")")+'</td></tr>').join('')+'</tbody></table></div></section>'}
function opsTicketsPanel(){return I18n.html("<section class=\"card\"><h2>Обращения сотруднику</h2><p>Сообщения из Telegram и обратная связь по QR. Во время передачи человеку бот добавляет новые сообщения в обращение.</p>")+((opsState.tickets||[]).length?opsState.tickets.map(t=>'<div class="row"><div><b>№'+t.id+' · '+esc(t.data.name)+'</b><small>'+esc(t.data.category)+' · '+esc(I18n.t(opsStatusNames[t.data.status]))+' · '+esc(t.data.summary.slice(0,160))+'</small></div>'+opsButton('Открыть','opsOpenTicket('+t.id+')')+'</div>').join(''):empty('Новых обращений пока нет.'))+'</section>'}
function opsOpenTicket(id){const t=opsState.tickets.find(x=>Number(x.id)===id),d=t.data;modal('Обращение №'+id,'<p>'+esc(d.summary)+'</p><p>'+esc(d.contact||'')+'</p><div class="result">'+d.messages.map(m=>'<p><b>'+esc({client:'Клиент',staff:'Сотрудник',internal:'Внутренняя заметка'}[m.role]||m.role)+' · '+esc(m.at)+'</b><br>'+esc(m.text)+'</p>').join('')+'</div><form onsubmit="opsUpdateTicket(event,'+id+')"><div class="fields">'+opsSelect('status','Статус',[['open','Новое'],['working','В работе'],['resolved','Решено']],d.status)+opsSelect('assigned_staff_id','Ответственный',opsStaffOptions(),d.assigned_staff_id)+textfield('note','Внутренняя заметка')+I18n.html("</div><button class=\"btn\">Сохранить</button></form>")+(d.chat_id?'<hr><form onsubmit="opsReplyTicket(event,'+id+')">'+textfield('text','Ответ клиенту в Telegram')+I18n.html("<button class=\"btn\">Отправить клиенту</button></form>"):I18n.html("<p class=\"hint\">Для ответа используйте контакт, который оставил клиент.</p>")))}
async function opsUpdateTicket(ev,id){ev.preventDefault();const r=await opsAction('ops_ticket_update',{id,...formData(ev.target)});if(r)$('modal').close()}
async function opsReplyTicket(ev,id){ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{await api('ops_ticket_reply',{id,text:ev.target.text.value});await reload();opsOpenTicket(id);toast('Ответ доставлен')}catch(e){toast(e.message);b.disabled=false}}
function opsResultsPanel(){return I18n.html("<section class=\"card\"><h2>Результат работы приложения</h2><form onsubmit=\"opsGetReport(event)\"><div class=\"fields\">")+field('from','С даты','date',today().slice(0,7)+'-01','required')+field('to','По дату','date',today(),'required')+I18n.html("</div><div class=\"actions\"><button class=\"btn\">Показать отчёт</button></div></form><div id=\"opsReport\">")+(opsReportResult?opsReportHtml(opsReportResult):I18n.html("<p class=\"hint\">Выберите период. Демонстрационные заказы исключены.</p>"))+I18n.html("</div></section><section class=\"card\" style=\"margin-top:20px\"><h2>Сигналы упущенного спроса</h2><p>Это подтверждённые текстом запросы, а не доказанные потерянные продажи. Откройте исходные сообщения перед решением о закупке или изменении цены.</p>")+opsDemandHtml()+I18n.html("</section><section class=\"card\" style=\"margin-top:20px\"><h2>Акции с учётом продаж</h2><p>После публикации идеи свяжите её ресурс с позицией каталога и создайте промокод. Цена и срок проверяются при каждом заказе.</p>")+opsButton('Связать опубликованную акцию','opsOpenCampaign()')+(opsState.campaigns||[]).map(c=>'<div class="row"><b>'+esc(c.data.code)+' · '+esc(c.data.name)+'</b><span>'+esc(c.data.valid_until)+'</span></div>').join('')+'</section>'}
function opsDemandHtml(){const rows=opsState.demands||[],groups={};for(const r of rows){const key=r.reason+'|'+r.topic;groups[key]??={...r,count:0};groups[key].count++}return Object.values(groups).map(g=>'<details class="row" style="display:block"><summary><b>'+esc(g.topic)+' — '+g.count+I18n.html(" обращений</b> · ")+esc({missing_item:'Нет товара',price:'Отказ из-за цены',no_slot:'Нет подходящего времени'}[g.reason])+'</summary>'+rows.filter(r=>r.reason===g.reason&&r.topic===g.topic).map(r=>'<p>'+esc(r.created_at)+' · '+esc(r.excerpt)+I18n.html(" <a href=\"#inbox\">Сообщение №")+r.source_id+'</a></p>').join('')+'</details>').join('')||empty('Пока нет зафиксированных сигналов.')}
function opsReportHtml(r){return '<div class="grid stats" style="margin-top:20px">'+[['Завершённые заказы',r.completed_orders],['Через Telegram',r.telegram_orders],['Продажи',money(r.sales)],['Отмеченные возвраты',money(r.refunds)],['Выручка после возвратов',money(r.net_sales)],['Валовая прибыль',r.gross_profit===null?I18n.t("Нужна сверка"):money(r.gross_profit)],['Расходы периода',money(r.expenses)],['Результат после расходов',r.after_expenses===null?I18n.t("Нужна сверка"):money(r.after_expenses)]].map(([n,v])=>'<div class="stat"><label>'+n+'</label><strong>'+v+'</strong></div>').join('')+I18n.html("</div><p>Завершённых визитов: ")+r.completed_visits+I18n.t(". Открытых обращений: ")+r.open_tickets+I18n.t(". Заказов без полной себестоимости: ")+r.unknown_cost_orders+'.</p><p class="hint">'+esc(r.note)+'</p>'+Object.entries(r.campaigns).map(([k,v])=>I18n.html("<div class=\"row\"><b>Промокод ")+esc(k)+'</b><span>'+v.orders+I18n.t(" заказов · ")+money(v.sales)+'</span></div>').join('')}
async function opsGetReport(ev){ev.preventDefault();try{opsReportResult=await api('ops_report',formData(ev.target));$('opsReport').innerHTML=opsReportHtml(opsReportResult)}catch(e){toast(e.message)}}
function opsOpenCampaign(){modal('Промокод опубликованной акции','<form onsubmit="opsSubmitSimple(event,\'ops_campaign_save\')"><div class="fields">'+opsSelect('promotion_id','Опубликованная акция',(state.promotion_drafts||[]).filter(x=>x.data.status==='published').map(x=>[x.id,x.data.name,true]))+opsSelect('item_id','Позиция каталога',opsItemOptions())+field('code','Промокод','text','','required pattern="[A-Za-z0-9_-]{3,30}"')+I18n.html("</div><p class=\"hint\">Исходная партия или свободный ресурс должны быть связаны с выбранной позицией. Срок, цена и лимит берутся из проверенной акции.</p><button class=\"btn\">Создать промокод</button></form>"))}
async function opsSubmitSimple(ev,action){ev.preventDefault();const r=await opsAction(action,{data:formData(ev.target)});if(r)$('modal').close()}
function opsBudgetPanel(){return I18n.html("<section class=\"card\"><h2>Набор под бюджет</h2><form onsubmit=\"opsBuildBudget(event)\"><div class=\"fields\">")+field('budget','Общий бюджет, ₸','number','','min="1" step="0.01" required')+field('people','Количество человек','number',1,'min="1" max="30" required')+textfield('preferences','Что подобрать','Например, завтрак на двоих: кофе и выпечка')+I18n.html("</div><button class=\"btn\">Подобрать варианты</button></form><div id=\"opsBudgetResults\"></div></section>")}
let opsBudgetOptions=[];async function opsBuildBudget(ev){ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{const r=await api('ops_budget',formData(ev.target));opsBudgetOptions=r.options;$('opsBudgetResults').innerHTML=r.options.map((o,i)=>'<section class="card" style="margin-top:16px"><h3>'+esc(o.name)+'</h3>'+o.quote.items.map(x=>'<div class="row"><span>'+esc(x.name)+' × '+x.quantity+'</span><b>'+money(x.total)+'</b></div>').join('')+I18n.html("<p>Всего ")+money(o.quote.total)+I18n.t(" · Осталось ")+money(o.remaining)+(o.quote.is_demo?I18n.t(" · Демонстрация"):'')+'</p>'+opsButton('Собрать заказ','opsOpenOrder(opsBudgetOptions['+i+'].quote.items)',false)+'</section>').join('')}catch(e){toast(e.message)}finally{b.disabled=false}}
function opsScenarioPanel(){return I18n.html("<section class=\"card\"><h2>Что будет, если изменить цену или себестоимость?</h2><form onsubmit=\"opsCalculateScenario(event)\"><div class=\"fields\">")+opsSelect('item_id','Позиция',opsItemOptions())+field('quantity','Базовый объём продаж за выбранный вами период','number','','min="0" step="0.001" required')+field('price_delta','Изменение цены, ₸','number',100,'step="0.01" required')+field('cost_delta','Изменение себестоимости, ₸','number',0,'step="0.01" required')+I18n.html("</div><button class=\"btn\">Рассчитать сценарии</button></form><div id=\"opsScenarioResults\"></div></section>")}
async function opsCalculateScenario(ev){ev.preventDefault();try{const r=await api('ops_scenario',formData(ev.target));$('opsScenarioResults').innerHTML='<h3>'+esc(r.item)+': '+money(r.old_price)+' → '+money(r.new_price)+I18n.html("</h3><div class=\"tablewrap\"><table><thead><tr><th>Изменение спроса</th><th>Количество</th><th>Выручка</th><th>Валовая прибыль</th><th>Изменение прибыли</th></tr></thead><tbody>")+r.scenarios.map(x=>'<tr><td>'+x.volume_change+'%</td><td>'+x.quantity+'</td><td>'+money(x.revenue)+'</td><td>'+(x.gross_profit===null?I18n.t("Неизвестна себестоимость"):money(x.gross_profit))+'</td><td>'+(x.profit_change===null?'—':money(x.profit_change))+'</td></tr>').join('')+'</tbody></table></div><p class="hint">'+esc(r.note)+'</p>'}catch(e){toast(e.message)}}
function opsSuppliersPanel(){return I18n.html("<section class=\"card\"><div class=\"sectiontitle\"><h2>Прайс-листы поставщиков</h2>")+opsButton('Добавить предложение','opsOpenSupplier()',false)+I18n.html("</div><p>ИИ распознаёт таблицы, текст и фото. До сравнения подтвердите упаковку, единицу, минимальный заказ и доставку.</p>")+(opsState.suppliers||[]).map(s=>'<details class="row" style="display:block"><summary>'+esc(s.data.supplier)+' · '+s.data.rows.length+I18n.t(" позиций · доставка ")+money(s.data.shipping)+'</summary>'+s.data.rows.map(r=>'<p>'+esc(r.name)+' — '+money(r.pack_price)+' / '+r.pack_units+' '+esc(r.unit)+I18n.t("; минимум ")+r.min_packs+I18n.t(" уп.; ключ «")+esc(r.match_key)+'»</p>').join('')+'</details>').join('')+I18n.html("</section><section class=\"card\" style=\"margin-top:20px\"><h2>Где выгоднее нужный объём?</h2><form onsubmit=\"opsCompareSupplierUI(event)\"><div class=\"fields\">")+field('match_key','Подтверждённый ключ одинакового товара','text','','required placeholder="Например, молоко 3,2%"')+field('unit','Одинаковая базовая единица','text','л','required')+field('quantity','Нужно базовых единиц','number','','min="0.001" step="0.001" required')+I18n.html("</div><button class=\"btn\">Сравнить с доставкой</button></form><div id=\"opsSupplierCompare\"></div></section>")}
function opsOpenSupplier(){modal('Новое предложение поставщика','<div class="fields">'+textfield('supplier_text','Текст или таблица','Вставьте прайс, сообщение поставщика или условия доставки')+I18n.html("<div class=\"field\"><label for=\"opsSupplierFile\">Excel, CSV, TXT или фото до 4 МБ</label><input id=\"opsSupplierFile\" type=\"file\" accept=\".xlsx,.xls,.csv,.txt,image/jpeg,image/png,image/webp\" onchange=\"opsReadSupplier(this)\"></div></div><div class=\"actions\">")+opsButton('Разобрать с ИИ','opsParseSupplier(this)',false)+opsButton('Заполнить вручную','opsSupplierManual()')+'</div><div id="opsSupplierError"></div>');opsSupplierDraft={image:null}}
async function opsFileData(file){return new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function opsReadSupplier(input){try{const f=input.files[0];if(!f)return;if(f.size>4000000)throw Error('Файл до 4 МБ');if(f.type.startsWith('image/'))opsSupplierDraft.image=await opsFileData(f);else{const rows=await readImportRows(f);$('f_supplier_text').value=rows.map(r=>r.join('\t')).join('\n');opsSupplierDraft.image=null}}catch(e){toast(e.message)}}
async function opsParseSupplier(b){b.disabled=true;try{opsSupplierDraft=await api('ops_supplier_parse',{text:$('f_supplier_text').value,image:opsSupplierDraft.image});opsShowSupplierReview()}catch(e){$('opsSupplierError').textContent=e.message;b.disabled=false}}
function opsSupplierManual(){opsSupplierDraft={supplier:'',shipping:0,rows:[{name:'',match_key:'',unit:'шт.',pack_units:1,pack_price:'',min_packs:1}]};opsShowSupplierReview()}
function opsShowSupplierReview(){modal('Проверьте предложение','<form onsubmit="opsSaveSupplierUI(event)"><div class="fields">'+field('supplier','Поставщик','text',opsSupplierDraft.supplier||'','required')+field('shipping','Доставка на заказ, ₸','number',opsSupplierDraft.shipping??'','min="0" step="0.01" required')+field('valid_until','Прайс действует до','date')+textfield('note','Условия и ограничения')+I18n.html("</div><p class=\"notice\">Сравниваются только позиции с одинаковыми подтверждёнными ключом и единицей. Проверьте бренд, характеристики и качество самостоятельно; литры и килограммы не взаимозаменяемы.</p><div class=\"tablewrap\"><table><thead><tr><th>Товар</th><th>Ключ сопоставления</th><th>Единица</th><th>В упаковке</th><th>Цена упаковки</th><th>Минимум упаковок</th></tr></thead><tbody>")+opsSupplierDraft.rows.map((r,i)=>'<tr>'+['name','match_key','unit','pack_units','pack_price','min_packs'].map((k,j)=>'<td><input id="opsSupp'+i+k+'" value="'+esc(r[k]??'')+'" type="'+(j<3?'text':'number')+'" '+(j>=3?'min="'+(k==='min_packs'?'1':'0.001')+'" step="'+(k==='min_packs'?'1':'0.001')+'"':'')+' required aria-label="'+esc(k)+' '+(i+1)+'"></td>').join('')+'</tr>').join('')+I18n.html("</tbody></table></div><button class=\"btn\">Сохранить проверенный прайс</button></form>"))}
async function opsSaveSupplierUI(ev){ev.preventDefault();const d=formData(ev.target);d.rows=opsSupplierDraft.rows.map((_,i)=>Object.fromEntries(['name','match_key','unit','pack_units','pack_price','min_packs'].map(k=>[k,$('opsSupp'+i+k).value])));const r=await opsAction('ops_supplier_save',{data:d});if(r)$('modal').close()}
let opsSupplierComparison={};async function opsCompareSupplierUI(ev){ev.preventDefault();try{opsSupplierComparison=formData(ev.target);const r=await api('ops_supplier_compare',opsSupplierComparison);$('opsSupplierCompare').innerHTML=r.offers.map((o,i)=>'<div class="card" style="margin-top:16px"><h3>'+esc(o.supplier)+(i===0?I18n.t(" · минимальная сумма"):'')+'</h3><p>'+o.packs+I18n.t(" упаковок = ")+o.received+' '+esc(o.unit)+I18n.t(". Товары ")+money(o.goods_total)+I18n.t(" + доставка ")+money(o.shipping)+'</p><h2>'+money(o.total)+I18n.html("</h2><p class=\"hint\">Цена единицы с доставкой: ")+money(o.effective_unit_price)+'</p>'+opsButton('Подготовить заявку','opsMakeSupplierDraft('+o.supplier_id+','+o.row_index+')')+'</div>').join('')||I18n.html("<p>Нет проверенных предложений с таким ключом и единицей.</p>")}catch(e){toast(e.message)}}
async function opsMakeSupplierDraft(supplier_id,row_index){try{const r=await api('ops_supplier_draft',{...opsSupplierComparison,supplier_id,row_index});modal('Черновик заявки','<div class="result">'+esc(r.text)+I18n.html("</div><p>Сохранено в «Мои документы». Поставщику ничего не отправлено.</p>"));await reload()}catch(e){toast(e.message)}}
function opsShiftsPanel(){return I18n.html("<section class=\"card\"><h2>Передать смену</h2><form onsubmit=\"opsParseShiftUI(event)\">")+textfield('shift_text','Что произошло и что нужно сделать','Напишите или запишите голосом')+I18n.html("<div class=\"actions\"><button class=\"btn\">Подготовить задачи</button>")+opsButton('🎙 Записать голосом',"opsRecordVoice('f_shift_text',this)")+I18n.html("</div><p class=\"hint\">До 90 секунд. Запись передаётся Google Gemini для расшифровки; задачи сохранятся после проверки.</p></form></section><section class=\"card\" style=\"margin-top:20px\"><h2>Смены и задачи</h2>")+(opsState.shifts||[]).map(s=>'<details style="margin:20px 0" open><summary><b>'+esc(s.data.name)+' · '+esc(s.created_at)+'</b></summary><p>'+esc(s.data.summary)+'</p>'+s.data.tasks.map((t,i)=>'<div class="row"><div><b>'+esc(t.name)+'</b><small>'+esc(t.text)+' · '+esc(opsState.staff.find(x=>Number(x.id)===Number(t.assigned_staff_id))?.name||'Не назначен')+' · '+esc(t.priority)+'</small></div>'+opsButton(t.status==='done'?I18n.t("Вернуть в работу"):I18n.t("Выполнено"),'opsShiftTaskUI('+s.id+','+i+','+(t.status!=='done')+')')+'</div>').join('')+'</details>').join('')+'</section>'}
async function opsRecordVoice(target,button){if(opsRecorder?.state==='recording'){opsRecorder.stop();return}try{opsRecordingStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];opsRecorder=new MediaRecorder(opsRecordingStream);opsRecorder.ondataavailable=e=>chunks.push(e.data);opsRecorder.onstop=async()=>{clearTimeout(opsRecordTimer);opsRecordingStream.getTracks().forEach(t=>t.stop());button.disabled=true;button.textContent=I18n.t("Распознаём…");try{const mime=(opsRecorder.mimeType||'audio/webm').split(';')[0],blob=new Blob(chunks,{type:mime});if(blob.size>8000000)throw Error('Запись слишком большая');const r=await api('ops_transcribe',{audio:await opsFileData(blob)});if($(target))$(target).value=r.text;toast('Проверьте распознанный текст')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent=I18n.t("🎙 Записать голосом")}};opsRecorder.start();button.textContent=I18n.t("Остановить запись");opsRecordTimer=setTimeout(()=>{if(opsRecorder.state==='recording')opsRecorder.stop()},90000)}catch(e){toast('Микрофон недоступен. Можно написать текст.')}}
async function opsParseShiftUI(ev){ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{opsShiftDraft=await api('ops_shift_parse',{text:ev.target.shift_text.value});modal('Проверьте передачу смены','<form onsubmit="opsSaveShiftUI(event)">'+field('name','Название смены','text','Смена '+today(),'required')+textfield('summary','Резюме','',opsShiftDraft.summary)+opsShiftDraft.tasks.map((t,i)=>'<section class="card" style="margin:12px 0">'+field('task_name_'+i,'Задача','text',t.name,'required')+textfield('task_text_'+i,'Детали','',t.text)+opsSelect('task_staff_'+i,'Ответственный',opsStaffOptions())+'</section>').join('')+I18n.html("<button class=\"btn\">Сохранить задачи смены</button></form>"))}catch(e){toast(e.message)}finally{b.disabled=false}}
async function opsSaveShiftUI(ev){ev.preventDefault();const f=ev.target,d={name:f.elements.namedItem('name').value,summary:f.summary.value,source:opsShiftDraft.source,tasks:opsShiftDraft.tasks.map((t,i)=>({name:f['task_name_'+i].value,text:f['task_text_'+i].value,priority:t.priority,assigned_staff_id:Number(f['task_staff_'+i].value)}))};const r=await opsAction('ops_shift_save',{data:d});if(r)$('modal').close()}
async function opsShiftTaskUI(id,index,done){await opsAction('ops_shift_task',{id,index,done})}
function opsPassportsPanel(){return I18n.html("<section class=\"card\"><div class=\"sectiontitle\"><h2>История обслуживания</h2>")+opsButton('＋ Карточка','opsOpenPassport()',false)+I18n.html("</div><p>Заказ, автомобиль, ремонт техники или курс обучения: статусы, события и фото. По персональной ссылке показываются только сведения, отмеченные для клиента.</p>")+(opsState.passports||[]).map(p=>'<div class="row"><div><b>'+esc(p.data.name)+'</b><small>'+esc(p.data.client)+' · '+esc(p.data.status)+'</small></div><div class="actions">'+opsButton('Карточка','opsOpenPassport('+p.id+')')+opsButton('Добавить событие','opsPassportEventUI('+p.id+')')+(opsState.role==='owner'?opsButton('Ссылка клиенту',"opsShareLink('passport',"+p.id+")"):'')+'</div></div>').join('')+'</section>'}
function opsOpenPassport(id=0){const d=opsState.passports.find(x=>Number(x.id)===id)?.data||{};modal(id?'История обслуживания':'Новая карточка','<form onsubmit="opsSavePassportUI(event,'+id+')"><div class="fields">'+field('name','Объект / заказ / курс','text',d.name||'','required')+field('client','Клиент — внутреннее поле','text',d.client||'')+field('status','Статус для клиента','text',d.status||'Принят','required')+textfield('public_summary','Описание для клиента','',d.public_summary||'')+textfield('terms','Согласованные условия / гарантия для клиента','',d.terms||'')+textfield('private_note','Внутренняя заметка — скрыта от клиента','',d.private_note||'')+I18n.html("</div><button class=\"btn\">Сохранить</button></form>")+(d.events||[]).map(e=>'<div class="row"><div><b>'+esc(e.at)+' · '+(e.public?I18n.t("Видно клиенту"):I18n.t("Внутренняя запись"))+'</b><small>'+esc(e.text)+I18n.t(" · фото: ")+(e.photos||[]).length+'</small></div></div>').join(''))}
async function opsSavePassportUI(ev,id){ev.preventDefault();const r=await opsAction('ops_passport_save',{data:{id,...formData(ev.target)}});if(r)$('modal').close()}
function opsPassportEventUI(id){modal('Добавить событие','<form onsubmit="opsSavePassportEvent(event,'+id+')">'+textfield('text','Что выполнено / следующий шаг')+I18n.html("<div class=\"field\"><label for=\"opsPassportPhoto\">Фото до 4 МБ, по желанию</label><input id=\"opsPassportPhoto\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\"></div><label><input type=\"checkbox\" name=\"public\"> Показывать этот текст и фото клиенту по персональной ссылке</label><div class=\"actions\"><button class=\"btn\">Добавить событие</button></div></form>"))}
async function opsSavePassportEvent(ev,id){ev.preventDefault();try{const file=$('opsPassportPhoto').files[0];if(file&&file.size>4000000)throw Error('Фото до 4 МБ');const r=await api('ops_passport_event',{id,text:ev.target.text.value,public:ev.target.public.checked,image:file?await opsFileData(file):null});$('modal').close();await opsRefresh();toast('Событие добавлено')}catch(e){toast(e.message)}}
async function opsShareLink(kind,id=0,rotate=false){try{const r=await api('ops_link',{kind,id,rotate});modal(kind==='feedback'?'QR обратной связи':'Персональная ссылка клиента','<p>'+(kind==='feedback'?I18n.t("Разместите QR на столе, чеке или стойке. Посетитель сможет написать или записать голосовое сообщение."):I18n.t("По ссылке видны статус, описание, условия и события, отмеченные для клиента. Внутренние заметки скрыты."))+'</p><div id="opsQr" style="max-width:220px;margin:20px auto"></div><p style="overflow-wrap:anywhere"><a target="_blank" rel="noopener noreferrer" href="'+esc(r.url)+'">'+esc(r.url)+'</a></p><div class="actions">'+opsButton('Скачать QR','opsDownloadQr()')+opsButton('Закрыть старую ссылку и создать новую',"opsShareLink('"+kind+"',"+id+",true)")+'</div>');const qr=qrcode(0,'M');qr.addData(r.url);qr.make();$('opsQr').innerHTML=qr.createSvgTag({scalable:true,margin:4})}catch(e){toast(e.message)}}
function opsDownloadQr(){dl($('opsQr').innerHTML,'aulieata-qr.svg','image/svg+xml')}
function opsFeedbackPanel(){const q=(opsState.tickets||[]).filter(t=>t.data.channel==='qr'),counts={};q.forEach(t=>counts[t.data.category]=(counts[t.data.category]||0)+1);return I18n.html("<section class=\"card\"><h2>Обратная связь по QR</h2><p>Посетитель оставляет текст или голос. После проверки расшифровки сообщение попадает в обращения сотруднику. Все темы обрабатываются одинаково.</p>")+opsButton('Получить ссылку и QR',"opsShareLink('feedback')",false)+'<div style="margin-top:20px">'+Object.entries(counts).map(([k,v])=>'<div class="row"><b>'+esc(k)+'</b><span>'+v+I18n.html(" обращений</span></div>")).join('')+'</div><div class="actions">'+opsButton('Открыть обращения',"opsGo('tickets')")+'</div></section>'}
function opsImportsPanel(){return I18n.html("<section class=\"card\"><h2>Импорты и отмена изменений</h2>")+opsButton('Импортировать таблицу',"openSmartImport('catalog')",false)+I18n.html("<p>Импорт показывает добавления и обновления до сохранения. Отмена остановится, если запись позже менялась или уже участвует в заказах.</p>")+(opsState.imports||[]).map(i=>I18n.html("<div class=\"row\"><div><b>Импорт №")+i.id+' · '+esc(I18n.t(opsStatusNames[i.data.state]))+'</b><small>'+i.data.changes.length+I18n.t(" строк · ")+esc(i.created_at)+'</small></div></div>').join('')+I18n.html("<h3>Журнал действий</h3>")+(opsState.audit||[]).map(a=>'<div class="row"><div><b>'+esc({import:'Импорт',catalog_edit:'Изменение каталога',owner_plan:'План владельца',order_create:'Создание заказа',order_status:'Статус заказа',stock_sale:'Списание по заказу',stock_return:'Возврат на склад',batch_edit:'Партия',undo:'Отмена изменения',appointment_create:'Новая запись',appointment_status:'Статус записи',appointment_move:'Перенос записи',staff_invite:'Приглашение сотрудника',staff_revoke:'Отключение сотрудника',schedule_save:'Рабочий график',ticket_reply:'Ответ клиенту'}[a.kind]||a.kind)+'</b><small>'+esc(a.created_at)+' · '+(a.actor==='owner'?I18n.t("Владелец"):a.actor==='telegram_owner'?I18n.t("Владелец через Telegram"):esc(a.actor))+'</small></div>'+(!Number(a.undone)&&['import','catalog_edit','owner_plan'].includes(a.kind)?opsButton('Отменить изменение','opsReviewUndo('+a.id+')'):'')+'</div>').join('')+'</section>'}
function opsReviewUndo(id){modal('Отменить изменение',I18n.html("<p>Будут восстановлены прежние значения. Если данные уже изменились или используются в заказах, отмена остановится.</p>")+opsButton('Проверить и отменить','opsDoUndo('+id+')',false))}
async function opsDoUndo(id){const r=await opsAction('ops_undo',{id},'Изменение отменено');if(r)$('modal').close()}
function opsTeamPanel(){return I18n.html("<section class=\"card\"><h2>Команда и доступ</h2><p>Оператор работает с заказами, записями, обращениями, сменами и обслуживанием. Менеджер также ведёт каталог, партии, поставщиков и отчёты. Настройки бота, приглашения и помощник владельца доступны владельцу.</p><form onsubmit=\"opsInviteStaff(event)\"><div class=\"fields\">")+field('name','Имя сотрудника','text','','required')+opsSelect('role','Роль',[['operator','Оператор'],['manager','Менеджер']])+I18n.html("</div><button class=\"btn\">Создать приглашение</button></form>")+(opsState.staff||[]).map(s=>'<div class="row"><div><b>'+esc(s.name)+'</b><small>'+esc(s.role==='operator'?I18n.t("Оператор"):I18n.t("Менеджер"))+' · '+(Number(s.active)?s.login?I18n.t("Доступ включён"):I18n.t("Приглашён"):I18n.t("Доступ отключён"))+'</small></div>'+(Number(s.active)?opsButton('Отключить','opsRevokeStaff('+s.id+')'):'')+'</div>').join('')+I18n.html("<p><a href=\"staff.php\" target=\"_blank\" rel=\"noopener\">Страница входа сотрудника</a></p></section>")}
async function opsInviteStaff(ev){ev.preventDefault();try{const r=await api('ops_staff_invite',formData(ev.target));await reload();modal('Приглашение сотрудника',I18n.html("<p>Передайте эту одноразовую ссылку сотруднику. Он сам создаст логин и пароль. Ссылка действует 3 дня.</p><p style=\"overflow-wrap:anywhere\">")+esc(r.url)+'</p>')}catch(e){toast(e.message)}}
function opsRevokeStaff(id){modal('Отключить сотрудника',I18n.html("<p>Доступ к данным этого бизнеса будет закрыт, в том числе в уже открытой сессии.</p>")+opsButton('Отключить доступ','opsApplyRevoke('+id+')',false))}
async function opsApplyRevoke(id){const r=await opsAction('ops_staff_revoke',{id});if(r)$('modal').close()}
function opsDeliveryPanel(){const labels={queued:'В очереди',sending:'Отправляется',sent:'Доставлено в Telegram',failed:'Не отправлено',unknown:'Доставка не подтверждена',cancelled:'Отменено'};return I18n.html("<section class=\"card\" style=\"margin-top:20px\"><h2>Доставка уведомлений</h2><p>Напоминания и изменения статусов отправляет фоновый обработчик. Если доставка не подтверждена, проверьте подключение и переписку перед повторной отправкой.</p>")+((opsState.outbox||[]).length?I18n.html("<div class=\"tablewrap\"><table><thead><tr><th>Событие</th><th>Время UTC+5</th><th>Состояние</th></tr></thead><tbody>")+opsState.outbox.map(r=>'<tr><td>'+esc(r.ref_key)+'</td><td>'+esc(r.due_at)+'</td><td>'+esc(I18n.t(labels[r.status]||r.status))+'</td></tr>').join('')+'</tbody></table></div>':empty('Уведомлений пока нет.'))+'</section>'}
function opsSetupPanel(){const c=state.catalog||[],s=opsState.settings||{},live=c.filter(x=>x.details?.data_mode!=='demo'),unknown=live.filter(x=>!x.details?.availability||x.details.availability==='unknown'),ready=[['Сфера бизнеса выбрана',!!state.profile?.type,'settings'],['Есть проверенные товары или услуги',live.length>0,'catalog'],['Наличие проверенных позиций заполнено',live.length>0&&!unknown.length,'catalog'],['Telegram подключён',!!Number(state.connection?.active),'settings'],['Мастера и рабочее время заданы',(opsState.resources||[]).some(x=>Number(x.active)),'bookings']];return I18n.html("<section class=\"card\"><h2>Подготовить бизнес к работе</h2>")+ready.map(([name,ok,route])=>'<div class="row"><b>'+(ok?'✓':'○')+' '+esc(I18n.t(name))+'</b><a href="#'+route+I18n.html("\">Открыть</a></div>")).join('')+I18n.html("<p>Проверенных позиций: ")+live.length+I18n.t(". Демонстрационных: ")+(c.length-live.length)+I18n.t(". С неизвестным наличием: ")+unknown.length+I18n.html(".</p><form onsubmit=\"opsSaveSetup(event)\"><div class=\"field\"><label for=\"botMode\">Режим Telegram-бота</label><select id=\"botMode\" name=\"bot_mode\"><option value=\"free\" ")+((s.bot_mode||'free')==='free'?'selected':'')+I18n.html(">Бесплатный: текст, каталог, заказы и сотрудник</option><option value=\"cloud\" ")+(s.bot_mode==='cloud'?'selected':'')+I18n.html(">Облачный ИИ бесплатно — квота Cloudflare</option><option value=\"ai\" ")+(s.bot_mode==='ai'?'selected':'')+I18n.html(">С ИИ и голосом — зависит от квоты Google</option></select><small>Облачный ИИ использует подключение Cloudflare и его бесплатный лимит. При исчерпании квоты остаются каталог, корзина, запись и сотрудник. Текст переписки и публичные сведения передаются в Cloudflare.</small></div><p><label><input type=\"checkbox\" name=\"orders_enabled\" ")+(s.orders_enabled?'checked':'')+I18n.html("> Принимать заказы через Telegram после подтверждения клиента</label></p><p><label><input type=\"checkbox\" name=\"bot_collect_contact\" ")+(s.bot_collect_contact?'checked':'')+I18n.html("> Собирать имя, телефон (по желанию) и пожелание по получению перед подтверждением заказа</label></p><p><label><input type=\"checkbox\" name=\"bookings_enabled\" ")+(s.bookings_enabled?'checked':'')+I18n.html("> Принимать записи через Telegram</label></p><p><label><input type=\"checkbox\" name=\"auto_confirm_booking\" ")+(s.auto_confirm_booking?'checked':'')+I18n.html("> Автоматически подтверждать свободное время по настроенному расписанию</label></p><div class=\"fields\">")+textfield('pickup_note','Правила получения заказа','',s.pickup_note||'')+field('reminder_hours','За сколько часов напоминать','number',s.reminder_hours||24,'min="1" max="72" required')+field('feedback_title','Заголовок формы обратной связи','text',s.feedback_title||'Расскажите, как прошло посещение')+I18n.html("</div><p class=\"hint\">Напоминания отправляются только клиентам, согласившимся на них. Доставка проверяется планировщиком. Демонстрационные позиции создают только демонстрационные заказы.</p><button class=\"btn\">Сохранить настройки</button></form></section>")+opsDeliveryPanel()}
async function opsSaveSetup(ev){ev.preventDefault();const d=formData(ev.target);for(const k of ['orders_enabled','bookings_enabled','auto_confirm_booking','bot_collect_contact'])d[k]=ev.target[k].checked;await opsAction('ops_settings_save',{data:d})}
function opsOwnerPanel(){return I18n.html("<section class=\"card\"><h2>Помощник владельца: от запроса до результата</h2><p>«Мороженое закончилось», «Поставь цену латте 1400», «Какие обращения ждут ответа?». Сначала проверяйте план, затем подтверждайте изменения.</p><form onsubmit=\"opsPlanOwnerUI(event)\">")+textfield('owner_text','Задача владельца')+I18n.html("<div class=\"actions\"><button class=\"btn\">Подготовить план</button>")+opsButton('🎙 Записать голосом',"opsRecordVoice('f_owner_text',this)")+opsButton('Включить режим владельца в Telegram','opsOwnerCodeUI()')+I18n.html("</div></form><div id=\"opsOwnerResult\"></div></section><section class=\"card\" style=\"margin-top:20px\"><h2>Последние действия помощника</h2>")+(opsState.plans||[]).slice(0,15).map(p=>'<div class="row"><div><b>'+esc(p.data.name)+'</b><small>'+esc(I18n.t(opsStatusNames[p.data.state]))+' · '+esc(p.data.result||p.data.error||p.data.summary.slice(0,160))+'</small></div>'+(p.data.audit_id?opsButton('История / отмена',"opsGo('imports')"):'')+'</div>').join('')+'</section>'}
async function opsPlanOwnerUI(ev){ev.preventDefault();const b=ev.target.querySelector('button');b.disabled=true;try{opsPlan=await api('ops_owner_plan',{text:ev.target.owner_text.value});$('opsOwnerResult').innerHTML='<div class="result" style="margin-top:20px">'+esc(opsPlan.summary)+'</div><div class="chips">'+opsPlan.steps.map(x=>'<span class="badge">'+(x.status==='done'?'✓ ':'○ ')+esc(x.name)+'</span>').join('')+'</div>'+opsPlan.actions.map((a,i)=>'<label class="row"><input type="checkbox" id="opsPlan'+i+'" checked><div><b>'+esc(a.kind==='catalog'?a.after.item_name:a.after.name)+'</b><small>'+(a.kind==='catalog'?money(a.before.item_price)+' → '+money(a.after.item_price)+' · '+esc(catalogAvailability[a.before.details.availability])+' → '+esc(catalogAvailability[a.after.details.availability]):esc(a.after.text))+'</small></div></label>').join('')+(opsPlan.actions.length?opsButton('Подтвердить выбранные действия','opsApplyOwnerUI(this)',false):'');await reload()}catch(e){toast(e.message)}finally{b.disabled=false}}
async function opsApplyOwnerUI(b){b.disabled=true;try{const selected=opsPlan.actions.map((_,i)=>i).filter(i=>$('opsPlan'+i).checked);const r=await api('ops_owner_apply',{id:opsPlan.id,selected});await opsRefresh();toast('Выполнено действий: '+r.count)}catch(e){toast(e.message);b.disabled=false}}
async function opsOwnerCodeUI(){try{const r=await api('ops_owner_code');modal('Личный режим владельца',I18n.html("<p>В своём Telegram-боте отправьте: <b>Я владелец ")+esc(r.code)+I18n.html("</b>.</p><p>Код одноразовый и действует 10 минут. Не передавайте его клиентам. Доступ владельца в этом чате будет активен 60 минут; выход — «Режим клиента».</p>"))}catch(e){toast(e.message)}}
async function opsReviewImportFromSmart(b){b.disabled=true;try{const rows=smartDraft.rows.flatMap((r,i)=>$('sr_pick_'+i).checked?[Object.fromEntries(Object.keys(importFields[smartDraft.target]).map(k=>[k,$('sr_'+i+'_'+k).value]))]:[]);const r=await api('ops_import_preview',{draft_id:smartDraft.draft_id,rows,mode:$('ops_import_mode')?.value||'add',prices_only:$('opsPricesOnly')?.checked??true});modal('Изменения перед импортом',I18n.html("<p>Проверьте каждую строку. Изменения ещё не сохранены.</p><div class=\"tablewrap\"><table><thead><tr><th>Действие</th><th>Позиция</th><th>До</th><th>После</th></tr></thead><tbody>")+r.changes.map(c=>'<tr><td>'+esc(I18n.t({add:'Добавить',update:'Обновить',skip:'Пропустить'}[c.action]))+'</td><td>'+esc(c.after?.item_name||c.after?.name||c.name||'')+'</td><td>'+(c.before?money(c.before.item_price)+'<br>'+esc(I18n.t(catalogAvailability[c.before.details.availability])):'—')+'</td><td>'+(c.kind==='catalog'&&c.after?money(c.after.item_price)+'<br>'+esc(I18n.t(catalogAvailability[c.after.details.availability]))+I18n.html("<br>Себестоимость: ")+money(c.after.item_cost)+I18n.t("; продано: ")+c.after.units_sold:c.after?esc(c.after.text||c.after.amount||c.after.quantity||'Новая запись'):I18n.t("Без изменений"))+'</td></tr>').join('')+'</tbody></table></div><div class="actions">'+opsButton('Применить изменения','opsApplyImportUI('+r.id+',this)',false)+'</div>')}catch(e){toast(e.message);b.disabled=false}}
async function opsApplyImportUI(id,b){b.disabled=true;try{const r=await api('ops_import_apply',{id});$('modal').close();await opsRefresh();toast('Применено: '+r.count+'. Пропущено: '+r.skipped)}catch(e){toast(e.message);b.disabled=false}}
